/// setter for IN DataPort
pub fn put_self_test_observation(value: Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestObservation)
{
  *extern_api::IN_self_test_observation.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_test_cycle_directive(value: Vehicle_Start_Readiness_Recovery_Supervisor::TestCycleDirective)
{
  *extern_api::IN_test_cycle_directive.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_cycle_assessment() -> Vehicle_Start_Readiness_Recovery_Supervisor::CycleAssessment
{
  return extern_api::OUT_cycle_assessment.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_committedTestCycle() -> Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.committedTestCycle,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_committedTestCycle(value: Vehicle_Start_Readiness_Recovery_Supervisor::CommittedTestCycle)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.committedTestCycle = value,
      None => panic!("The app is None")
    }
  }
}
